def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append((color, cells))

    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    result = [[0] * w for _ in range(h)]

    # Settle objects from right to left.
    objects.sort(key=lambda obj: max(c for _, c in obj[1]), reverse=True)

    for color, cells in objects:
        for cell in cells:
            occupied.remove(cell)

        shift = 0
        while all((r, c + shift + 1) not in occupied for r, c in cells):
            shift += 1

        moved = [(r, c + shift) for r, c in cells]
        for cell in moved:
            occupied.add(cell)
            result[cell[0]][cell[1]] = color

    return result
